import { describe, expect, it } from "vitest";
import { PRINT_PRESETS, applyPrintPresetToConfig, findPrintPreset } from "../printPresets";

const CONFIG = [
  "; generated by PrusaSlicer 2.9.6",
  "; layer_height = 0.15",
  "; perimeter_speed = 170",
  "; support_material_style = organic",
  "; support_tree_tip_diameter = 1.5",
].join("\n");

describe("print quality presets", () => {
  it("covers the five steps, finest to draft, with rising layer heights", () => {
    expect(PRINT_PRESETS.map((p) => p.id)).toEqual(["finest", "high", "normal", "fast", "draft"]);
    const heights = PRINT_PRESETS.map((p) => p.layerHeight);
    expect([...heights]).toEqual([...heights].sort((a, b) => a - b));
    for (const preset of PRINT_PRESETS) {
      expect(preset.settings.layer_height).toBe(String(preset.layerHeight));
      expect(preset.source).toMatch(/@XLIS 0\.4$/);
    }
  });

  it("rewrites the keys it owns and leaves the rest of the config alone", () => {
    const next = applyPrintPresetToConfig(CONFIG, findPrintPreset("finest")!);
    expect(next).toMatch(/^; layer_height = 0\.1$/m);
    expect(next).toMatch(/^; perimeter_speed = 140$/m);
    // Hand-tuned support settings are not a quality setting: they stay.
    expect(next).toMatch(/^; support_tree_tip_diameter = 1\.5$/m);
    expect(next).toMatch(/^; support_material_style = organic$/m);
    expect(next).toMatch(/^; generated by PrusaSlicer 2\.9\.6$/m);
  });

  it("adds keys a older template does not carry yet", () => {
    const next = applyPrintPresetToConfig("; layer_height = 0.2", findPrintPreset("high")!);
    expect(next).toMatch(/^; layer_height = 0\.15$/m);
    expect(next).toMatch(/^; top_solid_layers = 6$/m);
  });

  it("has no preset for an unknown id", () => {
    expect(findPrintPreset(null)).toBeNull();
    expect(findPrintPreset(undefined)).toBeNull();
  });
});
